// Original deterministic Web Audio/PCM instruments, not sampled acoustic instruments.
export const INSTRUMENTS=Object.freeze([
 ['piano','Piano',[1,.45,.22,.12],.004,.8,.22,.22],['epiano','Electric piano',[1,0,.5,0,.18],.006,.5,.4,.3],['organ','Organ',[1,.7,.35,.5],.015,.08,.85,.12],['bass','Electric-style bass',[1,.5,.15],.008,.3,.4,.15],['synthbass','Synth bass',[1,.3,.2,.15,.12],.012,.2,.55,.12],['sub','Sub bass',[1],.02,.08,.9,.2],['808','808-style bass',[1,.08],.004,.7,.12,.18],['lead','Lead synth',[1,.7,.45,.3,.2,.1],.02,.15,.7,.18],['pad','Pad synth',[1,.35,.16,.08],.3,.3,.6,.8],['pluck','Pluck synth',[1,.6,.3,.15],.003,.18,.06,.12],['retro','Retro synth',[1,0,.33,0,.2,0,.14],.005,.1,.65,.08],['guitar','Guitar-style',[1,.65,.4,.2,.1],.002,.5,.18,.2],['strings','Strings',[1,.55,.33,.22,.15],.15,.25,.65,.4],['bells','Bells',[1,.1,.65,0,.3],.002,.9,.12,.7],['flute','Flute-style',[1,.16,.08],.06,.1,.75,.2]
].map(([id,name,harmonics,attack,decay,sustain,release])=>Object.freeze({id,name,harmonics,attack,decay,sustain,release})));
export const patternBeats=p=>['notes','audio'].includes(p.kind)?p.beats:p.steps/4;
export const noteName=n=>['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'][n%12]+(Math.floor(n/12)-1);
export function instrumentSettings(pattern){const i=INSTRUMENTS.find(i=>i.id===pattern.instrument)||INSTRUMENTS[0];return{attack:i.attack,decay:i.decay,sustain:i.sustain,release:i.release,cutoff:12000,volume:.65,pan:0,...pattern.voice};}
export function validateNotes(p){const n=(v,a,b)=>Number.isFinite(v)&&v>=a&&v<=b;if(p.kind!=='notes'||!INSTRUMENTS.some(i=>i.id===p.instrument)||!n(p.beats,1,128)||!Array.isArray(p.notes)||p.notes.length>256)throw Error('Invalid Piano Roll pattern.');const ids=new Set();for(const x of p.notes){if(typeof x.id!=='string'||ids.has(x.id)||!Number.isInteger(x.pitch)||!n(x.pitch,24,108)||!n(x.start,0,p.beats)||!n(x.length,.03125,32)||x.start+x.length>p.beats+1e-6||!n(x.velocity,.01,1))throw Error('Invalid Piano Roll note.');ids.add(x.id);}const s=instrumentSettings(p);if(!n(s.attack,.001,2)||!n(s.decay,.01,3)||!n(s.sustain,0,1)||!n(s.release,.01,3)||!n(s.cutoff,100,18000)||!n(s.volume,0,1)||!n(s.pan,-1,1))throw Error('Invalid instrument settings.');return p;}
export function noteSampleId(p,n,bpm){const s=instrumentSettings(p);return 'note-'+[p.instrument,n.pitch,n.length,bpm,s.attack,s.decay,s.sustain,s.release,s.cutoff].join('-');}
export function synthNote(pattern,note,bpm,sr=44100){const instrument=INSTRUMENTS.find(i=>i.id===pattern.instrument)||INSTRUMENTS[0],s=instrumentSettings(pattern),held=note.length*60/bpm,duration=Math.min(132,held+s.release),out=new Float32Array(Math.ceil(duration*sr)),frequency=440*2**((note.pitch-69)/12),normal=instrument.harmonics.reduce((a,b)=>a+b,0)||1;let filtered=0;const coefficient=1-Math.exp(-2*Math.PI*Math.min(s.cutoff,sr*.45)/sr);
 for(let j=0;j<out.length;j++){const t=j/sr,envAt=v=>v<s.attack?v/s.attack:s.sustain+(1-s.sustain)*Math.exp(-(v-s.attack)/s.decay*4),env=t<=held?envAt(t):envAt(held)*Math.max(0,1-(t-held)/s.release),bend=instrument.id==='808'?1+.7*Math.exp(-t*28):1,vibrato=instrument.id==='strings'?1+.003*Math.sin(t*2*Math.PI*5):1;let v=0;for(let k=0;k<instrument.harmonics.length;k++){const f=frequency*(k+1)*vibrato;if(f>sr*.45)continue;const ratio=instrument.id==='bells'&&k===2?2.76:k+1;v+=instrument.harmonics[k]*Math.sin(2*Math.PI*frequency*ratio*t*bend)*(instrument.id==='piano'||instrument.id==='guitar'?Math.exp(-t*k*.7):1);}filtered+=coefficient*(v/normal-filtered);out[j]=Math.max(-.95,Math.min(.95,filtered*env*.8));}return out;}
export function ensureNoteSamples(patterns,buffers,context,bpm,retain=[]){if(!Number.isFinite(bpm)||bpm<60||bpm>200)throw Error('Choose a tempo from 60 to 200 BPM.');const needed=new Set(retain),plan=new Map();for(const p of patterns)if(p.kind==='notes'){validateNotes(p);for(const n of p.notes)plan.set(noteSampleId(p,n,bpm),{p,n});}let seconds=0;for(const {p,n}of plan.values())seconds+=n.length*60/bpm+instrumentSettings(p).release;if(seconds>128)throw Error('Use fewer unique sustained notes (128 seconds of instrument samples per project).');for(const [id,{p,n}]of plan){needed.add(id);if(!buffers.has(id)){const pcm=synthNote(p,n,bpm,22050),buffer=context.createBuffer(1,pcm.length,22050);buffer.copyToChannel(pcm,0);buffers.set(id,buffer);}}for(const id of buffers.keys())if(id.startsWith('note-')&&!needed.has(id))buffers.delete(id);}
